<?php
/** Production atomic seven-stage deletion, evidence races, preserved history and failures. */
declare(strict_types=1);
require __DIR__.'/support/reset-deletion.php';
use RodolfoRizzo\Cpt2Collection\{CommerceResetDeletion as D,CommerceResetRecord,CommerceResetRepository,TransactionManager,TableNames,CartRepository,OrderDeletionService,OrderDeletionRepository,OrderDeletionRegistry,UtcClock};
foreach([1,100,1000] as $size)foreach([false,true] as $sparse){
 $db=new DeletionDb('c2c_erasure_'.bin2hex(random_bytes(5)).'_');$t=new TableNames($db);try{
 [$r,$fixtures]=deletion_setup($db,3,$sparse);$keep=deletion_kept($db);$stock=deletion_stock($db);$svc=validation_service($db);
 foreach([0,1001] as $bad)check($svc->delete_operational($r,$bad)->code()==='invalid_request','invalid batch range rejected');
 $db->observe=true;$original=$r;$seen=[];
 for($n=0;$n<2000&&!D::certified_empty($r);++$n){[$stage,$pk]=D::position($r);$seen[$stage]=true;$before=$r;$r=($size===100?$svc->delete_operational($r):$svc->delete_operational($r,$size))->operation();check($r!==null&&$r->status()==='running','owned erasure batch succeeds');check($r->revision()===$before->revision()+1,'one exact revision advances batch/certificate');check(deletion_stock($db)===$stock,'physical stock byte unchanged per batch/transition');}
 $db->observe=false;check(D::certified_empty($r)&&$r->checkpoint()==='z1_n_0_done','all seven complete plus durable empty certificate');
 check(array_keys($seen)===['e','s','r','j','o','k','a','x'],'canonical stage order exact');
 foreach(D::STAGES as $table)check(!$db->get_results('SELECT id FROM '.$t->$table().' LIMIT 1'),'entire installation '.$table.' empty');
 check(deletion_kept($db)===$keep,'claims/tombstones/epochs/control/catalog/stock preserved');check($svc->delete_operational($original)->code()==='stale','same old snapshot cannot replay erasure');check($svc->delete_operational($r)->operation()->equals($r),'empty certificate repeat is idempotent');
 foreach($db->writes as $q)check(str_starts_with($q,'DELETE FROM ')||str_starts_with($q,'UPDATE `'.$db->prefix.'c2c_commerce_resets`'),'erasure only attempts exact deletes/reset progress');
 $front=D::position($r);$r=validation_bind($db,$r,$fixtures[0]['claim'],'event','evt_all_empty',hash('sha256','empty'),'checkout.session.completed');check(D::operational_empty($r)&&!D::certified_empty($r),'generation invalidates retained freshness but preserves empty fact');
 $db->reads=[];$db->observe=true;$r=deletion_retained($db,$r,1);$db->observe=false;
 check(D::certified_empty($r)&&D::position($r)[0]===$front[0],'retained certification converges with all operational tables empty');
 foreach(D::STAGES as $m)check(!array_filter($db->reads,fn($q)=>str_contains($q,$t->$m())),'retained restart reads no '.$m);
 check($r->target_epoch_id()===null&&$r->completed_at()===null&&$r->active_slot()===1&&$r->phase()==='deleting'&&$r->status()==='running','reset remains incomplete with unallocated target');check($db->get_var('SELECT retired_at FROM '.$t->commerce_epochs().' WHERE id='.$r->source_epoch_id())===null&&$db->get_var('SELECT state FROM '.$t->commerce_control())==='resetting','source unretired and commerce fenced');
 $tx=new TransactionManager($db,$t);check(!$tx->begin_commerce_shared()&&!$tx->begin_commerce_exclusive(),'checkout/cart/stock normal authority denied');check((new CartRepository($db,$t))->find_for_update($fixtures[0]['cart'])===false,'stale cart reference has no admitted authority');
 }finally{baseline_cleanup($db);}
}
// Real generation mutation before first batch, between batches, every boundary, late carts, pre-certificate.
foreach(['e','s','r','j','o','k','a','x'] as $stage)foreach([false,true] as $boundary){if($stage==='x'&&$boundary)continue;
 $db=new DeletionDb('c2c_erasure_gen_'.bin2hex(random_bytes(5)).'_');$t=new TableNames($db);try{
 [$r,$f]=deletion_setup($db);$r=deletion_pass($db,$r,1,$stage,$boundary);$p=D::position($r);$stock=deletion_stock($db);$snapshot=baseline_snapshot($db);
 $r=validation_bind($db,$r,$f[0]['claim'],'event','evt_stage_late',hash('sha256','late'),'checkout.session.completed');$db->writes=[];$db->reads=[];$db->observe=true;$stale=$r;$r=validation_service($db)->delete_operational($r,1)->operation();$db->observe=false;
 check(D::position($r)[0]===$p[0]&&D::position($r)[1]===$p[1]&&D::position($r)[2]==='c','generation restart preserves independent '.$stage.' frontier');check(!array_filter($db->writes,fn($q)=>str_starts_with($q,'DELETE ')),'stale certification performs no DELETE');check(validation_service($db)->delete_operational($stale)->code()==='stale','old evidence snapshot fenced');
 $db->reads=[];$db->observe=true;$r=deletion_retained($db,$r,1);$db->observe=false;foreach(D::STAGES as $m)check(!array_filter($db->reads,fn($q)=>str_contains($q,$t->$m())),'partial deletion retained pass needs no '.$m);
 $r=deletion_pass($db,$r,1);check(D::certified_empty($r)&&deletion_stock($db)===$stock,'late evidence resumes exact frontier and preserves stock');
 }finally{baseline_cleanup($db);}
}
// Each physical stage: rollback, DELETE/progress failure, behind/boundary anomalies and blocked evidence.
foreach(['below','exact'] as $anomaly)foreach(D::STAGES as $stage=>$method){$db=new DeletionDb('c2c_erasure_failure_'.bin2hex(random_bytes(5)).'_');$t=new TableNames($db);try{
 [$r,$f]=deletion_setup($db,3,true);$r=deletion_pass($db,$r,1,$stage);$snapshot=baseline_snapshot($db);$tx=new TransactionManager($db,$t);check($tx->begin_reset_deletion($r),'exact deletion authority');$repo=new CommerceResetRepository($db,$t);check($repo->delete_operational($r,1,gmdate('Y-m-d H:i:s'))!==false&&$tx->rollback(),'DELETE and frontier roll back together');check($snapshot===baseline_snapshot($db),'rollback preserves all durable rows and stock');
 foreach(['delete','progress','partial_delete'] as $fault){$db->fault=$fault;$db->delete_calls=0;$out=validation_service($db)->delete_operational($r,$fault==='partial_delete'?100:1);$db->fault='';check($out->code()==='database_error'&&$snapshot===baseline_snapshot($db),'known '.$fault.' failure atomically rolls back '.$method);}
 $r=validation_service($db)->delete_operational($r,1)->operation();$p=D::position($r);$seed=$db->get_row('SELECT * FROM '.$t->$method().' ORDER BY id LIMIT 1');$saved=$seed->id;
 foreach([$anomaly==='below'?$p[1]-1:$p[1]] as $bad){if($bad<1)continue;sql($db,'UPDATE '.$t->$method().' SET id='.$bad.' WHERE id='.$saved);$pre=$r;$r=validation_service($db)->delete_operational($r,1)->operation();check($r->status()==='blocked'&&D::position($r)===$p&&$r->cursor()===$pre->cursor(),'adversarial below/exact frontier blocks preserving position');check($r->error_code()==='deletion_behind_'.$method,'stable behind-frontier reason');$r=validation_bind($db,$r,$f[0]['claim'],'session','cs_block_'.$bad);check($r->status()==='blocked'&&validation_service($db)->delete_operational($r)->code()==='conflict','blocked sealed evidence admitted without automatic resume');break;}
 }finally{baseline_cleanup($db);}}
// Unsealed/stale/wrong exact contexts and capability separation.
$db=new DeletionDb('c2c_erasure_gates_'.bin2hex(random_bytes(5)).'_');$t=new TableNames($db);try{
 validation_schema($db);$f=validation_order($db);validation_receipt($db,$f,'evt_gate');$r=validation_start($db);check(validation_service($db)->delete_operational($r)->code()==='invalid_request','unsealed reset cannot delete');$r=retirement_pass($db,validation_pass($db,$r));$before=baseline_snapshot($db);$out=validation_service($db)->delete_operational($r);check($out->operation()->checkpoint()!=='z1_e_0_done','sealed incomplete retained pass cannot delete');$a=unserialize($before);$b=unserialize(baseline_snapshot($db));unset($a['commerce_resets'],$b['commerce_resets']);check(serialize($a)===serialize($b),'incomplete retained step preserves all operational rows');$r=deletion_retained($db,$out->operation());
 $tx=new TransactionManager($db,$t);check($tx->begin_reset_maintenance($r),'ordinary retained maintenance admitted');check((new CommerceResetRepository($db,$t))->delete_operational($r,1,gmdate('Y-m-d H:i:s'))===false&&$tx->rollback(),'ordinary maintenance lacks erasure capability');
 foreach(['operation_identity','source_epoch_identity'] as $field){$row=$db->get_row('SELECT * FROM '.$t->commerce_resets());$row->$field=bin2hex(random_bytes(16));check(validation_service($db)->delete_operational(CommerceResetRecord::from_row($row))->code()==='stale','wrong '.$field.' denied');}
 foreach([null,'z2_e_0_done','z1_e_00_done','z1_x_1_done','z1_e_zzzzzzzzzzzzzzzzzz_done'] as $cp){$row=$db->get_row('SELECT * FROM '.$t->commerce_resets());$row->checkpoint=$cp;check(validation_service($db)->delete_operational(CommerceResetRecord::from_row($row))->code()==='invalid_request','legacy/malformed/unrecognized seal rejected');}
 check(strlen(D::prefix('a',PHP_INT_MAX).'dc_'.\RodolfoRizzo\Cpt2Collection\CommerceResetRetirement::encode_cursor(PHP_INT_MAX))<=64,'independent max integer frontiers fit existing token');
 }finally{baseline_cleanup($db);}
// Lost COMMIT for each batch, each durable stage transition, and empty certification.
foreach(array_keys(D::STAGES) as $stage)foreach(['batch','transition'] as $position)foreach(['before','after'] as $fault){
 $prefix='c2c_erasure_loss_'.bin2hex(random_bytes(5)).'_';$db=new DeletionDb($prefix);try{[$r,$f]=deletion_setup($db,1,false,1);$r=deletion_pass($db,$r,100,$stage,$position==='transition');$snapshot=baseline_snapshot($db);$stock=deletion_stock($db);$db->fault=$fault;$out=validation_service($db)->delete_operational($r,100);check($out->code()==='transaction_outcome_unknown'&&$out->operation()===null&&!$db->transaction_connection_usable(),'uncertain '.$stage.'/'.$position.'/'.$fault.' poisons connection');$db->close();$db=new DeletionDb($prefix);$fresh=validation_service($db)->resume($r->operation_identity())->operation();check($fault==='before'?$fresh->equals($r):$fresh->revision()===$r->revision()+1,'fresh locked inspection determines batch/transition outcome');if($fault==='before')check(baseline_snapshot($db)===$snapshot,'connection close rolls back both effects');$fresh=deletion_pass($db,$fresh,100);check(D::certified_empty($fresh)&&deletion_stock($db)===$stock,'fresh retry reaches empty certificate without stock effect');}finally{baseline_cleanup($db);}}
foreach(['before','after'] as $fault){$prefix='c2c_erasure_empty_loss_'.bin2hex(random_bytes(5)).'_';$db=new DeletionDb($prefix);try{[$r]=deletion_setup($db,0);$r=deletion_pass($db,$r,1,'x');$db->fault=$fault;check(validation_service($db)->delete_operational($r)->code()==='transaction_outcome_unknown','empty certificate commit loss');$db->close();$db=new DeletionDb($prefix);$fresh=validation_service($db)->resume($r->operation_identity())->operation();check($fault==='before'?$fresh->equals($r):D::certified_empty($fresh),'durable inspection resolves empty certificate');check(D::certified_empty(deletion_pass($db,$fresh)),'empty stages and recovery converge');}finally{baseline_cleanup($db);}}
// Genuine Phase 3 tombstones and deleted claims survive erasure, unlike reset-retired claims.
$db=new DeletionDb('c2c_erasure_deleted_'.bin2hex(random_bytes(5)).'_');$t=new TableNames($db);try{
 validation_schema($db);$old=validation_order($db);$delete=new OrderDeletionService(new OrderDeletionRepository($db,$t),new OrderDeletionRegistry($db,$t),new TransactionManager($db,$t),new UtcClock());check($delete->delete($old['order'])->code()==='deleted','genuine Phase 3 deletion');$f=validation_order($db);validation_receipt($db,$f,'evt_survivor');$r=deletion_retained($db,retirement_pass($db,validation_pass($db,validation_start($db))));$keep=deletion_kept($db);$identities=serialize($db->get_results('SELECT * FROM '.$t->provider_identities().' ORDER BY id'));$r=deletion_pass($db,$r);check(D::certified_empty($r)&&deletion_kept($db)===$keep&&$identities===serialize($db->get_results('SELECT * FROM '.$t->provider_identities().' ORDER BY id')),'all genuine tombstones, claims and identities survive actual purge');$r=validation_bind($db,$r,$old['claim'],'event','evt_deleted_after',hash('sha256','after'),'checkout.session.completed');check(D::certified_empty(deletion_retained($db,$r)),'genuine deletion retained validation after complete purge');
 }finally{baseline_cleanup($db);}
echo "All operational deletion checks passed.\n";
